using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tool that fetches data from an external HTTP API.
/// HttpClient is injected via DI so callers can configure base address,
/// default headers, resilience policies, etc. in the service registration.
/// </summary>
internal class ApiFetchTool(HttpClient httpClient, ILogger<ApiFetchTool> logger)
{
    [McpServerTool(Name = "fetch_api")]
    [Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public async Task<string> FetchApiAsync(
        [Description("The absolute URL to send a GET request to.")] string url,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching URL: {Url}", url);

        try
        {
            using var response = await httpClient.GetAsync(url, cancellationToken);
            response.EnsureSuccessStatusCode();

            var body = await response.Content.ReadAsStringAsync(cancellationToken);

            // Return pretty-printed JSON when the response is valid JSON,
            // otherwise return the raw body.
            try
            {
                var doc = JsonDocument.Parse(body);
                return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
            }
            catch (JsonException)
            {
                return body;
            }
        }
        catch (HttpRequestException ex)
        {
            logger.LogError(ex, "HTTP request to {Url} failed", url);
            return $"Error: {ex.Message}";
        }
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

/// <summary>
/// Prompt templates exposed to MCP clients.
/// </summary>
internal class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize")]
    [Description("Generates a prompt that asks the model to summarize the given text.")]
    public static ChatMessage[] Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Desired length: 'short', 'medium', or 'long'.")] string length = "medium")
    {
        var systemMessage = new ChatMessage(
            ChatRole.System,
            $"You are a helpful assistant that summarizes text. Provide a {length}-length summary.");

        var userMessage = new ChatMessage(
            ChatRole.User,
            $"Please summarize the following text:\n\n{text}");

        return [systemMessage, userMessage];
    }
}

/// <summary>Simple role/content pair used by prompt templates.</summary>
internal sealed record ChatMessage(ChatRole Role, string Content);

/// <summary>Standard chat roles.</summary>
internal enum ChatRole
{
    System,
    User,
    Assistant
}

